int Mark(string name, int value) { Print(name); return value; }
class Order {
    public int First = Mark("field", 1);
    public int Count { get; init; } = Mark("property", 2);
    private int total;
    public int Total { get => total; init { Print("init:" + value); total = value; } }
    public Order(int n = 0) { Print("constructor:" + n); }
}
void Main() {
    var order = new Order(Mark("argument", 4)) { First = Mark("first", 5), Total = Mark("total", 6), Count = Mark("count", 7), };
    Print(order.First); Print(order.Total); Print(order.Count);
    new Order { Count = 8 }; new Order {};
}
